Here is the commit message:
fs/ntfs3: prevent infinite loops caused by the next valid
 being the same

When processing valid within the range [valid : pos), if valid cannot
be retrieved correctly, for example, if the retrieved valid value is
always the same, this can trigger a potential infinite loop, similar
to the hung problem reported by syzbot [1].

Adding a check for the valid value within the loop body, and terminating
the loop and returning -EINVAL if the value is the same as the current
value, can prevent this.

[1]
INFO: task syz.4.21:6056 blocked for more than 143 seconds.
Call Trace:
 rwbase_write_lock+0x14f/0x750 kernel/locking/rwbase_rt.c:244
 inode_lock include/linux/fs.h:1027 [inline]
 ntfs_file_write_iter+0xe6/0x870 fs/ntfs3/file.c:1284

Fixes: 4342306f0f0d ("fs/ntfs3: Add file operations and implementation")
Reported-by: syzbot+bcf9e1868c1a0c7e04f1@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=bcf9e1868c1a0c7e04f1
Signed-off-by: Edward Adam Davis <eadavis@qq.com>
Signed-off-by: Konstantin Komarov <almaz.alexandrovich@paragon-software.com>

Here is the root cause:
In `fs/ntfs3/file.c`, the loop in `ntfs_compress_write` for sparse clusters (`lcn == SPARSE_LCN`) updates `ni->i_valid` and `valid` to a computed value, but if that computed value equals the current `ni->i_valid` (e.g., due to `clen` being 0 or a corrupt mapping), the loop continues without making progress, resulting in an infinite hang.

Here is the patch:
  */
 static ssize_t ntfs_compress_write(struct kiocb *iocb, struct iov_iter *from)
 {
 	int err;
 	struct file *file = iocb->ki_filp;
 	size_t count = iov_iter_count(from);
 	loff_t pos = iocb->ki_pos;
 	struct inode *inode = file_inode(file);
 	loff_t i_size = i_size_read(inode);
 	struct address_space *mapping = inode->i_mapping;
 	struct ntfs_inode *ni = ntfs_i(inode);
 	u64 valid = ni->i_valid;
 	struct ntfs_sb_info *sbi = ni->mi.sbi;
 	struct page **pages = NULL;
 	struct folio *folio;
 	size_t written = 0;
 	u8 frame_bits = NTFS_LZNT_CUNIT + sbi->cluster_bits;
 	u32 frame_size = 1u << frame_bits;
 	u32 pages_per_frame = frame_size >> PAGE_SHIFT;
 	u32 ip, off;
 	CLST frame;
 	u64 frame_vbo;
 	pgoff_t index;
 	bool frame_uptodate;

 	if (frame_size < PAGE_SIZE) {
 		/*
 		 * frame_size == 8K if cluster 512
 		 * frame_size == 64K if cluster 4096
 		 */
 		ntfs_inode_warn(inode, "page size is bigger than frame size");
 		return -EOPNOTSUPP;
 	}

 	pages = kmalloc_array(pages_per_frame, sizeof(struct page *), GFP_NOFS);
 	if (!pages)
 		return -ENOMEM;

 	err = file_remove_privs(file);
 	if (err)
 		goto out;

 	err = file_update_time(file);
 	if (err)
 		goto out;

 	/* Zero range [valid : pos). */
 	while (valid < pos) {
 		CLST lcn, clen;

 		frame = valid >> frame_bits;
 		frame_vbo = valid & ~(frame_size - 1);
 		off = valid & (frame_size - 1);

 		err = attr_data_get_block(ni, frame << NTFS_LZNT_CUNIT, 1, &lcn,
 					  &clen, NULL, false, NULL);
 		if (err)
 			goto out;

 		if (lcn == SPARSE_LCN) {
-			ni->i_valid = valid =
-				frame_vbo + ((u64)clen << sbi->cluster_bits);
+			valid = frame_vbo + ((u64)clen << sbi->cluster_bits);
+			if (ni->i_valid == valid) {
+				err = -EINVAL;
+				goto out;
+			}
+			ni->i_valid = valid;
 			continue;
 		}

 		/* Load full frame. */
 		err = ntfs_get_frame_pages(mapping, frame_vbo >> PAGE_SHIFT,
 					   pages, pages_per_frame,
 					   &frame_uptodate);
 		if (err)
 			goto out;

 		if (!frame_uptodate && off) {
 			err = ni_read_frame(ni, frame_vbo, pages,
 					    pages_per_frame, 0);
 			if (err) {
 				for (ip = 0; ip < pages_per_frame; ip++) {
 					folio = page_folio(pages[ip]);
 					folio_unlock(folio);
 					folio_put(folio);
 				}
 				goto out;
 			}
 		}

 		ip = off >> PAGE_SHIFT;
 		off = offset_in_page(valid);
 		for (; ip < pages_per_frame; ip++, off = 0) {
 			folio = page_folio(pages[ip]);
 			folio_zero_segment(folio, off, PAGE_SIZE);
 			flush_dcache_folio(folio);
 			folio_mark_uptodate(folio);
 		}

 		ni_lock(ni);
 		err = ni_write_frame(ni, pages, pages_per_frame);
 		ni_unlock(ni);

 		for (ip = 0; ip < pages_per_frame; ip++) {
 			folio = page_folio(pages[ip]);
 			folio_mark_uptodate(folio);
 			folio_unlock(folio);
 			folio_put(folio);
 		}

 		if (err)
 			goto out;

 		ni->i_valid = valid = frame_vbo + frame_size;
 	}

 	/* Copy user data [pos : pos + count). */
 	while (count) {
 		size_t copied, bytes;

 		off = pos & (frame_size - 1);
 		bytes = frame_size - off;
 		if (bytes > count)
 			bytes = count;

 		frame_vbo = pos & ~(frame_size - 1);
 		index = frame_vbo >> PAGE_SHIFT;

 		if (unlikely(fault_in_iov_iter_readable(from, bytes))) {
 			err = -EFAULT;
 			goto out;
 		}

 		/* Load full frame. */
 		err = ntfs_get_frame_pages(mapping, index, pages,
 					   pages_per_frame, &frame_uptodate);
 		if (err)
 			goto out;

 		if (!frame_uptodate) {
 			loff_t to = pos + bytes;

 			if (off || (to < i_size && (to & (frame_size - 1)))) {
 				err = ni_read_frame(ni, frame_vbo, pages,
 						    pages_per_frame, 0);
 				if (err) {
 					for (ip = 0; ip < pages_per_frame;
 					     ip++) {
 						folio = page_folio(pages[ip]);
 						folio_unlock(folio);
 						folio_put(folio);
 					}
 					goto out;
 				}
 			}
 		}

 		WARN_ON(!bytes);
 		copied = 0;
 		ip = off >> PAGE_SHIFT;
 		off = offset_in_page(pos);

 		/* Copy user data to pages. */
 		for (;;) {
 			size_t cp, tail = PAGE_SIZE - off;

 			folio = page_folio(pages[ip]);
 			cp = copy_folio_from_iter_atomic(
 				folio, off, min(tail, bytes), from);
 			flush_dcache_folio(folio);

 			copied += cp;
 			bytes -= cp;
 			if (!bytes || !cp)
 				break;

 			if (cp < tail) {
 				off += cp;
 			} else {
 				ip++;
 				off = 0;
 			}
 		}

 		ni_lock(ni);
 		err = ni_write_frame(ni, pages, pages_per_frame);
 		ni_unlock(ni);

 		for (ip = 0; ip < pages_per_frame; ip++) {
 			folio = page_folio(pages[ip]);
 			folio_clear_dirty(folio);
 			folio_mark_uptodate(folio);
 			folio_unlock(folio);
 			folio_put(folio);
 		}

 		if (err)
 			goto out;

 		/*
 		 * We can loop for a long time in here. Be nice and allow
 		 * us to schedule out to avoid softlocking if preempt
 		 * is disabled.
 		 */
 		cond_resched();

 		pos += copied;
 		written += copied;

 		count = iov_iter_count(from);
 	}

 out:
 	kfree(pages);

 	if (err < 0)
 		return err;

 	iocb->ki_pos += written;
 	if (iocb->ki_pos > ni->i_valid)
 		ni->i_valid = iocb->ki_pos;
 	if (iocb->ki_pos > i_size)
 		i_size_write(inode, iocb->ki_pos);

 	return written;
 }



